// project initialization
namespace SpriteKind {
    export let Title = SpriteKind.create()
    export let Monkey = SpriteKind.create()
}

let statusbar = statusbars.create(0, 0, StatusBarKind.Health)
let player: Sprite = null
let gameStart = false
let spriteDirection = "right"

function startGame() {
    scene.setBackgroundColor(0)
    tiles.setCurrentTilemap(assets.tilemap`level`)
    gameStart = true

    player = sprites.create(assets.image`playerRight`, SpriteKind.Player)
    tiles.placeOnTile(player, tiles.getTileLocation(5, 5))
    controller.moveSprite(player)
    scene.cameraFollowSprite(player)
    player.z = 5

    for (let location of tiles.getTilesByType(assets.tile`spawnTile`)) {
        let monkeySprite= sprites.create(assets.image`monkeyImage`, SpriteKind.Monkey)
        createStatusBar(monkeySprite)
        tiles.placeOnTile(monkeySprite, location)
        monkeySprite.setScale(randint(1, 1.5))
        tiles.setTileAt(location, assets.tile`coverTile`)
    }
}

function createStatusBar(sprite: Sprite) {
    statusbar = statusbars.create(20, 4, StatusBarKind.Health)
    statusbar.value = 0
    statusbar.max = 4
    statusbar.setColor(5, 2)
}

function sendFood() {
    if (gameStart) {
        timer.after(500, function () {
            let projectile = sprites.createProjectileFromSprite(assets.image`bananaImage`, player, 0, 0)
            if (spriteDirection == "right") {
                projectile.vx = 80
            } else if (spriteDirection == "left") {
                projectile.vx = -80
            }
        })
    }
}

function monkeyFull(sprite: Sprite) {
    sprite.setFlag(SpriteFlag.GhostThroughSprites, true)
    sprite.startEffect(effects.smiles)
}

// project start 
scene.setBackgroundColor(7)
let textScreen = sprites.create(assets.image`titleText`, SpriteKind.Title)

sprites.destroyAllSpritesOfKind(SpriteKind.Title)
story.printDialog("Move the Player around the tilemap to feed the hungry monkeys! Then, use the A button to send the monkeys bananas.", 80, 60, 70, 150, 1, 0)
startGame()

// project events
controller.right.onEvent(ControllerButtonEvent.Pressed, function () {
    if (gameStart) {
        player.setImage(assets.image`playerRight`)
        spriteDirection = "right"
    }
})

controller.left.onEvent(ControllerButtonEvent.Pressed, function () {
    if (gameStart) {
        player.setImage(assets.image`playerLeft`)
        spriteDirection = "left"
    }
})

controller.A.onEvent(ControllerButtonEvent.Pressed, function () {
    sendFood()
})

sprites.onOverlap(SpriteKind.Projectile, SpriteKind.Monkey, function (sprite, otherSprite) {
    sprites.destroy(sprite)
    statusbars.getStatusBarAttachedTo(StatusBarKind.Health, otherSprite) += 1
    if (statusbars.getStatusBarAttachedTo(StatusBarKind.Health, otherSprite) == 4) {
        monkeyFull(otherSprite)
    }
})
